@props([ 'type' => null, 'message' => null, 'title' => null, ]) <div id="ui-toast-container" class="ui-toast-container"> @php $flashes = [ 'success' => session('success'), 'error' => session('error') ?: session('danger'), 'warning' => session('warning'), 'info' => session('info') ?: session('status'), ]; @endphp @if($type && $message) <script>document.addEventListener('DOMContentLoaded', () => { if (window.DapToast) { window.DapToast.{{ $type }}('{{ addslashes($message) }}', '{{ addslashes($title ?? ucfirst($type)) }}'); } });</script> @endif @foreach($flashes as $flashType => $flashMsg) @if($flashMsg) <script>document.addEventListener('DOMContentLoaded', () => { if (window.DapToast) { window.DapToast.{{ $flashType }}('{{ addslashes($flashMsg) }}'); } });</script> @endif @endforeach </div>